import React, { useState, useEffect } from 'react';
import axios from 'axios';

export default function Overview() {
  // ගණන් තියාගන්න State එකක්
  const [stats, setStats] = useState({ subjects: 0, students: 0, teachers: 0 });

  useEffect(() => {
    // Database එකෙන් දත්ත අරන් ගණන් කරන කොටස
    const fetchStats = async () => {
      try {
        const subRes = await axios.get('http://localhost:8081/api/view-subjects');
        const stuRes = await axios.get('http://localhost:8081/api/view-students');
        const teaRes = await axios.get('http://localhost:8081/api/view-teachers');

        setStats({
          subjects: subRes.data.length || 0,
          students: stuRes.data.length || 0,
          teachers: teaRes.data.length || 0
        });
      } catch (err) {
        console.error("Error fetching stats:", err);
      }
    };

    fetchStats();
  }, []);

  return (
    <div style={{ padding: '30px', fontFamily: 'sans-serif' }}>
      
      {/* Welcome Banner එක */}
      <div style={{ 
        backgroundColor: '#15803d', 
        color: 'white', 
        padding: '30px', 
        borderRadius: '15px', 
        marginBottom: '40px',
        boxShadow: '0 10px 25px rgba(21, 128, 61, 0.3)'
      }}>
        <h1 style={{ margin: '0 0 10px 0', fontSize: '28px' }}>Welcome back, Admin! 👋</h1>
        <p style={{ margin: '0', fontSize: '16px', opacity: '0.9' }}>
          Here is what's happening in your system today.
        </p>
      </div>

      {/* Stats Cards (කොටු 3) */}
      <div style={{ display: 'flex', gap: '25px', flexWrap: 'wrap' }}>
        
        {/* Subjects Card */}
        <div style={{ flex: 1, minWidth: '250px', backgroundColor: '#fff', padding: '25px', borderRadius: '15px', borderLeft: '6px solid #0284c7', boxShadow: '0 4px 15px rgba(0,0,0,0.05)' }}>
          <h3 style={{ margin: '0 0 10px 0', color: '#64748b', fontSize: '16px' }}>Total Subjects</h3>
          <h2 style={{ margin: '0', fontSize: '36px', color: '#0f172a' }}>{stats.subjects}</h2>
        </div>

        {/* Students Card */}
        <div style={{ flex: 1, minWidth: '250px', backgroundColor: '#fff', padding: '25px', borderRadius: '15px', borderLeft: '6px solid #f59e0b', boxShadow: '0 4px 15px rgba(0,0,0,0.05)' }}>
          <h3 style={{ margin: '0 0 10px 0', color: '#64748b', fontSize: '16px' }}>Total Students</h3>
          <h2 style={{ margin: '0', fontSize: '36px', color: '#0f172a' }}>{stats.students}</h2>
        </div>

        {/* Teachers Card */}
        <div style={{ flex: 1, minWidth: '250px', backgroundColor: '#fff', padding: '25px', borderRadius: '15px', borderLeft: '6px solid #10b981', boxShadow: '0 4px 15px rgba(0,0,0,0.05)' }}>
          <h3 style={{ margin: '0 0 10px 0', color: '#64748b', fontSize: '16px' }}>Total Teachers</h3>
          <h2 style={{ margin: '0', fontSize: '36px', color: '#0f172a' }}>{stats.teachers}</h2>
        </div>

      </div>

      {/* පොඩි Description එකක් */}
      <div style={{ marginTop: '40px', backgroundColor: '#f8fafc', padding: '20px', borderRadius: '10px', border: '1px solid #e2e8f0' }}>
        <p style={{ margin: 0, color: '#475569', lineHeight: '1.6' }}>
          💡 <strong>Tip for the panel:</strong> All these statistics are updated in real-time directly from the MySQL database!
        </p>
      </div>

    </div>
  );
}
